.venv/bin/python - <<'EOF'
import re, json, pathlib
changed={}
for f in ("API_MAP.md","PLATFORM_SAYS.md","NOTES.md","PLAN.md","README.md"):
    p=pathlib.Path(f); lines=p.read_text().split("\n"); out=[]; open_=False; n=0
    for i,l in enumerate(lines):
        if l.startswith("```"):
            if not open_:
                lang=l[3:].strip(); open_=True
                # collect block body to decide
                j=i+1; body=[]
                while j<len(lines) and not lines[j].startswith("```"): body.append(lines[j]); j+=1
                txt="\n".join(body)
                if lang=="json":
                    try: json.loads(txt)
                    except Exception: lang="text"; n+=1
                elif lang=="":
                    lang="text"; n+=1
                out.append("```"+lang)
            else:
                open_=False; out.append("```")
        else: out.append(l)
    if n: p.write_text("\n".join(out)); changed[f]=n
print("retagged fences:", changed)
# also check the generated digest script emits tagged fences
s=pathlib.Path("scripts/error_digest.py").read_text()
print("digest uses:", set(re.findall(r'```(\w*)', s)))
EOF
grep -c '^```$' API_MAP.md PLATFORM_SAYS.md; grep -n '^```' API_MAP.md | head

